css:
.digitalpivot-container {
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    max-width: 1080px;
    margin: 0 auto;
    padding: 24px;
    color: #20242e;
    background: linear-gradient(165deg, #fbf7f1 0%, #f3eee6 55%, #ece6dc 100%);
    border-radius: 18px;
}

.digitalpivot-container * {
    box-sizing: border-box;
}

.digitalpivot-header {
    text-align: center;
    padding: 28px 22px 24px;
    background: linear-gradient(135deg, #161b3d 0%, #2a2f63 50%, #4b3a86 100%);
    color: #f6f4ff;
    border-radius: 16px;
    margin-bottom: 18px;
    box-shadow: 0 14px 34px rgba(22, 27, 61, 0.32);
}

.digitalpivot-header h1 {
    margin: 10px 0 10px;
    font-size: 2.5rem;
    font-weight: 800;
    letter-spacing: -0.5px;
    color: #ffffff;
}

.digitalpivot-header-tag {
    display: inline-block;
    font-size: 0.74rem;
    text-transform: uppercase;
    letter-spacing: 1.2px;
    font-weight: 700;
    color: #ffcf7a;
    background: rgba(255, 207, 122, 0.14);
    border: 1px solid rgba(255, 207, 122, 0.40);
    padding: 5px 14px;
    border-radius: 999px;
}

.digitalpivot-subtitle {
    margin: 0 auto;
    max-width: 840px;
    font-size: 1rem;
    line-height: 1.55;
    color: #d9d6f0;
}

.digitalpivot-mandate {
    display: flex;
    align-items: center;
    gap: 14px;
    background: #ffffff;
    border-left: 5px solid #d98a1e;
    border-radius: 12px;
    padding: 14px 18px;
    margin-bottom: 18px;
    box-shadow: 0 6px 16px rgba(32, 36, 46, 0.08);
}

.digitalpivot-mandate-icon {
    font-size: 1.8rem;
    line-height: 1;
}

.digitalpivot-mandate-label {
    display: block;
    font-size: 0.72rem;
    text-transform: uppercase;
    letter-spacing: 0.8px;
    font-weight: 800;
    color: #b06d12;
    margin-bottom: 3px;
}

.digitalpivot-mandate-text {
    font-size: 0.94rem;
    line-height: 1.5;
    color: #3a3f4c;
}

.digitalpivot-mandate-text strong { color: #2a2f63; }

.digitalpivot-period-counter {
    display: flex;
    align-items: center;
    gap: 8px;
    flex-wrap: wrap;
    font-size: 0.96rem;
    font-weight: 600;
    color: #4a4f5e;
    margin-bottom: 16px;
    padding: 4px 4px;
}

.digitalpivot-period-counter #currentDay,
.digitalpivot-period-counter #maxPeriods {
    font-weight: 800;
    color: #4b3a86;
}

.digitalpivot-round-name {
    background: rgba(75, 58, 134, 0.13);
    color: #4b3a86;
    padding: 3px 12px;
    border-radius: 999px;
    font-size: 0.82rem;
    font-weight: 700;
    margin-left: 4px;
}

.digitalpivot-clock {
    margin-left: auto;
    font-size: 0.82rem;
    font-weight: 700;
    color: #b06d12;
    background: rgba(217, 138, 30, 0.14);
    border: 1px solid rgba(217, 138, 30, 0.32);
    padding: 4px 12px;
    border-radius: 999px;
}

.digitalpivot-status-cards {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 14px;
    margin-bottom: 16px;
}

.digitalpivot-status-card {
    background: #ffffff;
    border-radius: 14px;
    padding: 16px 16px 14px;
    box-shadow: 0 6px 16px rgba(32, 36, 46, 0.08);
    border-top: 4px solid #4b3a86;
}

.digitalpivot-card-share { border-top-color: #4b3a86; }
.digitalpivot-card-cac { border-top-color: #d98a1e; }
.digitalpivot-card-conv { border-top-color: #1f8a76; }
.digitalpivot-card-brand { border-top-color: #c0457a; }

.digitalpivot-label {
    font-size: 0.72rem;
    text-transform: uppercase;
    letter-spacing: 0.6px;
    font-weight: 700;
    color: #6b7080;
}

.digitalpivot-value {
    font-size: 2.6rem;
    font-weight: 800;
    line-height: 1.1;
    margin: 4px 0 2px;
    color: #20242e;
    font-variant-numeric: tabular-nums;
}

.digitalpivot-card-share .digitalpivot-value { color: #4b3a86; }
.digitalpivot-card-cac .digitalpivot-value { color: #c8780f; }
.digitalpivot-card-conv .digitalpivot-value { color: #1f8a76; }
.digitalpivot-card-brand .digitalpivot-value { color: #c0457a; }

.digitalpivot-sublabel {
    font-size: 0.75rem;
    color: #7a8090;
    line-height: 1.35;
}

/* State-driven KPI colouring (good / warn / loss). */
.digitalpivot-card-share.digitalpivot-good { border-top-color: #1f8a76; }
.digitalpivot-card-share.digitalpivot-good .digitalpivot-value { color: #1f8a76; }
.digitalpivot-card-share.digitalpivot-warn { border-top-color: #d98a1e; }
.digitalpivot-card-share.digitalpivot-warn .digitalpivot-value { color: #c8780f; }
.digitalpivot-card-share.digitalpivot-loss { border-top-color: #d64545; }
.digitalpivot-card-share.digitalpivot-loss .digitalpivot-value { color: #d64545; }

.digitalpivot-card-cac.digitalpivot-good { border-top-color: #1f8a76; }
.digitalpivot-card-cac.digitalpivot-good .digitalpivot-value { color: #1f8a76; }
.digitalpivot-card-cac.digitalpivot-loss { border-top-color: #d64545; }
.digitalpivot-card-cac.digitalpivot-loss .digitalpivot-value { color: #d64545; }

.digitalpivot-card-brand.digitalpivot-loss { border-top-color: #d64545; }
.digitalpivot-card-brand.digitalpivot-loss .digitalpivot-value { color: #d64545; }

.digitalpivot-roi-bar {
    display: flex;
    justify-content: space-between;
    align-items: center;
    background: #ffffff;
    border: 1px solid #e4ddd2;
    color: #4a4f5e;
    padding: 10px 18px;
    border-radius: 12px;
    margin-bottom: 18px;
    font-weight: 700;
    font-size: 0.92rem;
}

.digitalpivot-roi-bar #roiDisplay {
    font-size: 1.15rem;
    letter-spacing: 0.3px;
    color: #6b7080;
    font-weight: 800;
}

.digitalpivot-roi-bar.digitalpivot-roi-good #roiDisplay { color: #1f8a76; }
.digitalpivot-roi-bar.digitalpivot-roi-warn #roiDisplay { color: #c8780f; }
.digitalpivot-roi-bar.digitalpivot-roi-loss #roiDisplay { color: #d64545; }

.digitalpivot-briefing {
    display: flex;
    gap: 14px;
    background: #ffffff;
    border-left: 5px solid #4b3a86;
    border-radius: 12px;
    padding: 16px 18px;
    margin-bottom: 18px;
    box-shadow: 0 6px 16px rgba(32, 36, 46, 0.07);
}

.digitalpivot-briefing-icon {
    font-size: 1.8rem;
    line-height: 1;
}

.digitalpivot-briefing-title {
    font-weight: 800;
    font-size: 1.08rem;
    color: #2a2f63;
    margin-bottom: 6px;
}

.digitalpivot-briefing-text {
    font-size: 0.95rem;
    line-height: 1.55;
    color: #3c4151;
}

.digitalpivot-briefing-text strong { color: #4b3a86; }
.digitalpivot-briefing-text em { color: #c8780f; font-style: italic; }

.digitalpivot-controls {
    background: #ffffff;
    border-radius: 14px;
    padding: 20px 22px;
    margin-bottom: 18px;
    box-shadow: 0 6px 16px rgba(32, 36, 46, 0.07);
}

.digitalpivot-controls h3 {
    margin: 0 0 14px;
    font-size: 1.12rem;
    font-weight: 800;
    color: #2a2f63;
    border-bottom: 2px solid #ece6dc;
    padding-bottom: 8px;
}

.digitalpivot-panel label {
    display: block;
    font-weight: 700;
    font-size: 0.92rem;
    color: #2c313e;
    margin: 14px 0 6px;
}

.digitalpivot-panel label.digitalpivot-check {
    display: flex;
    align-items: flex-start;
    gap: 10px;
    font-weight: 600;
    font-size: 0.9rem;
    background: #faf8f3;
    border: 1px solid #e7e0d4;
    border-radius: 10px;
    padding: 12px 14px;
    margin: 8px 0 0;
    cursor: pointer;
    color: #3c4151;
}

.digitalpivot-panel label.digitalpivot-check input[type="checkbox"] {
    width: 18px;
    height: 18px;
    margin-top: 1px;
    accent-color: #4b3a86;
    flex: 0 0 auto;
}

.digitalpivot-container select,
.digitalpivot-container input[type="number"] {
    width: 100%;
    padding: 10px 12px;
    border: 1px solid #d2c9bb;
    border-radius: 9px;
    font-size: 0.92rem;
    background-color: #ffffff;
    color: #20242e;
    transition: border-color 0.15s, box-shadow 0.15s;
}

.digitalpivot-container select:focus,
.digitalpivot-container input[type="number"]:focus {
    outline: none;
    border-color: #4b3a86;
    box-shadow: 0 0 0 3px rgba(75, 58, 134, 0.16);
}

.digitalpivot-container select option {
    background-color: #ffffff;
    color: #20242e;
}

.digitalpivot-container input[type="range"] {
    width: 100%;
    margin: 8px 0 2px;
    accent-color: #4b3a86;
}

.digitalpivot-range-readout {
    font-size: 0.88rem;
    font-weight: 700;
    color: #4a4f5e;
    margin-top: 4px;
}

.digitalpivot-range-readout span:nth-child(2) {
    color: #4b3a86;
    font-weight: 800;
}

.digitalpivot-budget-readout {
    font-size: 0.95rem;
    font-weight: 800;
    color: #2a2f63;
    margin-top: 12px;
    padding: 10px 14px;
    background: #f3eee6;
    border-radius: 10px;
    border: 1px solid #e7e0d4;
}

.digitalpivot-budget-readout #martechCommitted {
    color: #c8780f;
}

.digitalpivot-budget-readout.digitalpivot-over #martechCommitted {
    color: #d64545;
}

.digitalpivot-hint {
    font-size: 0.8rem;
    color: #7a8090;
    margin-top: 6px;
    line-height: 1.4;
    font-style: italic;
}

.digitalpivot-container .btn {
    margin-top: 18px;
    font-weight: 700;
}

.digitalpivot-container .btn-primary {
    background: linear-gradient(135deg, #2a2f63 0%, #4b3a86 100%);
    border: none;
    color: #ffffff;
    padding: 11px 26px;
    border-radius: 9px;
    box-shadow: 0 8px 18px rgba(42, 47, 99, 0.32);
}

.digitalpivot-container .btn-primary:hover {
    filter: brightness(1.10);
}

.digitalpivot-container .btn-outline-secondary {
    margin-left: 10px;
    border: 1px solid #d2c9bb;
    color: #6b7080;
    background: transparent;
}

.digitalpivot-coach {
    background: linear-gradient(160deg, #161b3d 0%, #2a2f63 100%);
    color: #e6e3fa;
    border-radius: 14px;
    padding: 16px 20px;
    margin-bottom: 18px;
    box-shadow: 0 8px 20px rgba(22, 27, 61, 0.26);
}

.digitalpivot-coach-header {
    font-size: 0.78rem;
    text-transform: uppercase;
    letter-spacing: 1px;
    font-weight: 700;
    color: #ffcf7a;
    margin-bottom: 8px;
}

.digitalpivot-coach-body {
    font-size: 0.95rem;
    line-height: 1.55;
}

.digitalpivot-coach-body strong { color: #b6e7dd; }
.digitalpivot-coach-body em { color: #ffcf7a; font-style: italic; }

.digitalpivot-history,
.digitalpivot-chart {
    background: #ffffff;
    border-radius: 14px;
    padding: 18px 20px;
    margin-bottom: 18px;
    box-shadow: 0 6px 16px rgba(32, 36, 46, 0.07);
}

.digitalpivot-history h3,
.digitalpivot-chart h3 {
    margin: 0 0 14px;
    font-size: 1.08rem;
    font-weight: 800;
    color: #2a2f63;
}

.digitalpivot-container table#usfHistoryTable {
    width: 100%;
    font-size: 0.88rem;
    color: #3c4151;
}

.digitalpivot-container table#usfHistoryTable th {
    background: #f1edf7;
    color: #4b3a86;
    font-weight: 700;
    text-transform: uppercase;
    font-size: 0.72rem;
    letter-spacing: 0.4px;
    padding: 8px 10px;
    border-bottom: 2px solid #ddd3ec;
}

.digitalpivot-container table#usfHistoryTable td {
    padding: 8px 10px;
    border-bottom: 1px solid #eef1f3;
    color: #3c4151;
}

.digitalpivot-container table#usfHistoryTable tr:nth-child(even) td {
    background: #faf8fc;
}

.digitalpivot-chart canvas {
    max-width: 100%;
}

@media (max-width: 768px) {
    .digitalpivot-container {
        padding: 14px;
    }
    .digitalpivot-header h1 {
        font-size: 1.8rem;
    }
    .digitalpivot-status-cards {
        grid-template-columns: repeat(2, 1fr);
        gap: 10px;
    }
    .digitalpivot-value {
        font-size: 2rem;
    }
    .digitalpivot-clock {
        margin-left: 0;
    }
    .digitalpivot-period-counter {
        font-size: 0.88rem;
    }
    .digitalpivot-roi-bar {
        flex-direction: column;
        gap: 4px;
        align-items: flex-start;
    }
    .digitalpivot-mandate {
        flex-direction: column;
        align-items: flex-start;
    }
    .digitalpivot-container .btn-outline-secondary {
        margin-left: 0;
        margin-top: 8px;
        display: block;
        width: 100%;
    }
}

/* v1.1.0 completion scorecard (append-only, namespaced .dpv-cm-*) */
.dpv-cm { margin-top: 8px; }
.dpv-cm-incomplete { text-align: center; color: #2a2f63; font-size: 1rem; padding: 18px; }
.dpv-cm-head { display: flex; flex-wrap: wrap; gap: 16px; align-items: stretch; margin-bottom: 18px; }
.dpv-cm-score { flex: 0 0 auto; min-width: 150px; background: linear-gradient(135deg, #2a2f63 0%, #4b3a86 55%, #1f8a76 150%); color: #ffffff; border-radius: 14px; padding: 16px 22px; text-align: center; box-shadow: 0 8px 22px rgba(42,47,99,0.28); }
.dpv-cm-score-num { font-size: 2.9rem; font-weight: 800; line-height: 1; }
.dpv-cm-score-den { font-size: 1.1rem; font-weight: 600; opacity: 0.85; }
.dpv-cm-score-lbl { margin-top: 6px; font-size: 0.72rem; text-transform: uppercase; letter-spacing: 1px; font-weight: 700; color: #c7c0ec; }
.dpv-cm-verdict { flex: 1 1 220px; display: flex; flex-direction: column; justify-content: center; background: #f5f4fb; border: 1px solid #ddd8ef; border-radius: 14px; padding: 14px 20px; }
.dpv-cm-verdict-lbl { font-size: 0.72rem; text-transform: uppercase; letter-spacing: 1px; font-weight: 700; color: #7a74a0; }
.dpv-cm-verdict-tier { font-size: 1.5rem; font-weight: 800; color: #2a2f63; margin-top: 4px; line-height: 1.15; }
.dpv-cm-section { margin-bottom: 16px; }
.dpv-cm-section-h { font-size: 0.8rem; text-transform: uppercase; letter-spacing: 0.6px; font-weight: 700; color: #4b3a86; margin-bottom: 8px; border-bottom: 1px solid #ddd8ef; padding-bottom: 4px; }
.dpv-cm-chips { display: flex; flex-wrap: wrap; gap: 8px; }
.dpv-cm-chip { display: inline-flex; align-items: center; gap: 6px; padding: 6px 12px; border-radius: 999px; font-size: 0.85rem; font-weight: 600; border: 1px solid transparent; }
.dpv-cm-ok { background: #e6f2ee; color: #17604f; border-color: #bfe0d6; }
.dpv-cm-no { background: #fbe6e6; color: #b23434; border-color: #f0c2c2; }
.dpv-cm-ico { font-weight: 800; }
.dpv-cm-kpis { display: grid; grid-template-columns: repeat(4, 1fr); gap: 10px; }
.dpv-cm-kpi { background: #fbfbfe; border: 1px solid #ddd8ef; border-radius: 12px; padding: 12px 10px; text-align: center; }
.dpv-cm-kpi-val { font-size: 1.5rem; font-weight: 800; color: #4b3a86; line-height: 1; }
.dpv-cm-kpi-lbl { font-size: 0.78rem; font-weight: 700; color: #33365f; margin-top: 6px; }
.dpv-cm-kpi-sub { font-size: 0.68rem; color: #7a74a0; margin-top: 2px; }
.dpv-cm-insights { margin: 0; padding-left: 20px; color: #2a2f63; }
.dpv-cm-insights li { margin-bottom: 6px; line-height: 1.4; }
@media (max-width: 620px) { .dpv-cm-kpis { grid-template-columns: repeat(2, 1fr); } }

