(function() {
    'use strict';

    class DigitalPivotAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = `Digital Pivot`;
            this.version = `1.1.0`;

            this.ROUNDS = [
                { id: 1, titleKey: `briefing_title_r1`, textKey: `briefing_text_r1`, panelId: `round1Panel`, nameKey: `round_name_r1`, clockKey: `clock_r1` },
                { id: 2, titleKey: `briefing_title_r2`, textKey: `briefing_text_r2`, panelId: `round2Panel`, nameKey: `round_name_r2`, clockKey: `clock_r2` },
                { id: 3, titleKey: `briefing_title_r3`, textKey: `briefing_text_r3`, panelId: `round3Panel`, nameKey: `round_name_r3`, clockKey: `clock_r3` },
                { id: 4, titleKey: `briefing_title_r4`, textKey: `briefing_text_r4`, panelId: `round4Panel`, nameKey: `round_name_r4`, clockKey: `clock_r4` }
            ];

            // ---- Numbers reference card (Dom & Styl S.A.) ----
            this.START_SHARE = 11;        // digital revenue share (%) at start
            this.TARGET_SHARE = 20;       // board target in 4 quarters
            this.CHECKPOINT = 16;         // half-year checkpoint (≥16% by 30 Sep)
            this.START_CAC = 240;         // blended CAC (zł), up 34% in 2 yrs
            this.START_CONV = 1.4;        // online conversion (%), benchmark 2.6
            this.BENCH_CONV = 2.6;        // category conversion benchmark (%)
            this.START_BRAND = 71;        // unaided brand awareness (%)
            this.BUDGET = 64;             // frozen marketing budget (mln zł)
            this.MARTECH = 12;            // martech transformation envelope (mln zł)

            // Martech costs (mln zł) — replatform is the leverage play. At the
            // low end of the 9–14 quote it fits with attribution (9 + 2.5 ≤ 12),
            // so foundation-first is viable, but you still cannot also fund the
            // CDP (6) or the marketplace alongside it — you cannot fund everything.
            this.COST_REPLATFORM = 9;
            this.COST_CDP = 6;
            this.COST_ATTRIBUTION = 2.5;
            this.COST_MARKETPLACE = 3;
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    share: this.START_SHARE,        // digital revenue share (%)
                    cac: this.START_CAC,            // blended CAC (zł)
                    conversion: this.START_CONV,    // online conversion (%)
                    brand: this.START_BRAND,        // unaided brand awareness (%)
                    roi: 0,                         // transformation ROI (%) — computed from R3 on
                    roiSet: false,                  // has ROI been computed yet
                    brandPenaltyPending: 0,         // delayed awareness erosion queued from R2, fired in R4
                    martechSpent: 0,                // mln zł committed of the 12 envelope
                    replatform: false,
                    replatformPartial: false,       // funded but starved below full build
                    cdp: false,
                    attribution: false,
                    marketplace: false,
                    cutBrandHard: false,            // over-cut brand flag (decision tree #1)
                    spreadThin: false,              // funded breadth, starved leverage (decision tree #2)
                    skippedAttribution: false,      // could not prove ROI (decision tree #3)
                    cacChasing: false,              // optimised CAC by chasing discount-seekers (decision tree #5)
                    cededControl: false,            // treated pivot as IT / agency job (decision tree #4)
                    checkpointMiss: false,          // below 16% at the half-year
                    shareHistory: [this.START_SHARE],
                    convHistory: [this.START_CONV],
                    brandHistory: [this.START_BRAND],
                    cacHistory: [this.START_CAC],
                    lastCoach: ``
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                // Seeded defaults lean toward the classic errors — a blind
                // click-through must NOT auto-win.
                state.decisions = {
                    split: `allmeasurable`,
                    leak: `awareness`,
                    northstar: `spend`,
                    ownership: 40,
                    brandShift: 20,
                    floor: `nofloor`,
                    focus: `cheapclicks`,
                    convTarget: 1.8,
                    replatform: false,
                    cdp: false,
                    attribution: false,
                    marketplace: false,
                    sequence: `marketplace`,
                    narrative: `hitnumber`,
                    metric: `caconly`,
                    team: `winargument`,
                    conviction: 50
                };
            }
            this._updateBriefing(state);
        }

        validateDecisions(decisions) {
            const state = window.mySimulation.state;
            const round = state.currentPeriod || 1;
            const warn = (k) => window.mySimulation.uiManager.showNotification(window.mySimulation.t(k), `warning`);

            if (round === 1) {
                const sp = document.getElementById(`splitInput`);
                const lk = document.getElementById(`leakInput`);
                const ns = document.getElementById(`northstarInput`);
                const ow = document.getElementById(`ownershipInput`);
                if (sp) decisions.split = sp.value;
                if (lk) decisions.leak = lk.value;
                if (ns) decisions.northstar = ns.value;
                if (ow) decisions.ownership = parseInt(ow.value, 10);
                if (!Number.isFinite(decisions.ownership) || decisions.ownership < 0 || decisions.ownership > 100) {
                    warn(`warn_ownership_range`); return false;
                }
            } else if (round === 2) {
                const bs = document.getElementById(`brandShiftInput`);
                const fl = document.getElementById(`floorInput`);
                const fo = document.getElementById(`focusInput`);
                const ct = document.getElementById(`convTargetInput`);
                if (bs) decisions.brandShift = parseInt(bs.value, 10);
                if (fl) decisions.floor = fl.value;
                if (fo) decisions.focus = fo.value;
                if (ct) decisions.convTarget = parseFloat(ct.value);
                if (!Number.isFinite(decisions.brandShift) || decisions.brandShift < 0 || decisions.brandShift > 100) {
                    warn(`warn_brandshift_range`); return false;
                }
                if (!Number.isFinite(decisions.convTarget) || decisions.convTarget < 1.4 || decisions.convTarget > 3.0) {
                    warn(`warn_convtarget_range`); return false;
                }
            } else if (round === 3) {
                const rp = document.getElementById(`replatformInput`);
                const cd = document.getElementById(`cdpInput`);
                const at = document.getElementById(`attributionInput`);
                const mk = document.getElementById(`marketplaceInput`);
                const sq = document.getElementById(`sequenceInput`);
                if (rp) decisions.replatform = !!rp.checked;
                if (cd) decisions.cdp = !!cd.checked;
                if (at) decisions.attribution = !!at.checked;
                if (mk) decisions.marketplace = !!mk.checked;
                if (sq) decisions.sequence = sq.value;
                // At least one investment must be chosen.
                if (!decisions.replatform && !decisions.cdp && !decisions.attribution && !decisions.marketplace) {
                    warn(`warn_martech_none`); return false;
                }
            } else if (round === 4) {
                const na = document.getElementById(`narrativeInput`);
                const me = document.getElementById(`metricInput`);
                const tm = document.getElementById(`teamInput`);
                const cv = document.getElementById(`convictionInput`);
                if (na) decisions.narrative = na.value;
                if (me) decisions.metric = me.value;
                if (tm) decisions.team = tm.value;
                if (cv) decisions.conviction = parseInt(cv.value, 10);
                if (!Number.isFinite(decisions.conviction) || decisions.conviction < 0 || decisions.conviction > 100) {
                    warn(`warn_conviction_range`); return false;
                }
            }
            return true;
        }

        _composite(ds) {
            // v1.1.0 - verbatim v1.0.0 composite (was computed only in getPerformanceSummary and discarded).
            const share = Math.round(ds.share * 10) / 10;
            const cac = Math.round(ds.cac);
            const conversion = Math.round(ds.conversion * 100) / 100;
            const brand = Math.round(ds.brand);
            const roi = Math.round(ds.roi);
            const shareScore = Math.min(100, (share / this.TARGET_SHARE) * 100);
            const convScore = Math.min(100, ((conversion - this.START_CONV) / (this.BENCH_CONV - this.START_CONV)) * 100);
            const cacScore = Math.max(0, Math.min(100, (this.START_CAC / cac) * 100));
            const brandScore = Math.min(100, (brand / this.START_BRAND) * 100);
            const roiScore = Math.max(0, Math.min(100, 50 + roi * 0.6));
            return Math.round(shareScore * 0.30 + convScore * 0.20 + cacScore * 0.15 + brandScore * 0.15 + roiScore * 0.20);
        }

        calculateResults(state) {
            const d = state.decisions;
            const ds = state.domainState;
            const round = state.currentPeriod;

            let shareDelta = 0, cacDelta = 0, convDelta = 0, brandDelta = 0;
            let coachKey = `coach_default`;
            let summaryKey = `sum_default`;

            if (round === 1) {
                // ---- Diagnose: read the P&L, the funnel and the north star. ----
                switch (d.split) {
                    case `separate`: shareDelta += 1.0; convDelta += 0.02; coachKey = `coach_r1_separate`; break;
                    case `cutunattrib`: brandDelta -= 1; cacDelta += 4; coachKey = `coach_r1_cut`; break; // sets up the brand-as-dead-money error
                    case `allmeasurable`: cacDelta += 2; coachKey = `coach_r1_allmeas`; break;
                }

                switch (d.leak) {
                    case `conversion`: shareDelta += 1.2; convDelta += 0.04; coachKey = `coach_r1_conv`; break;
                    case `awareness`: cacDelta += 3; coachKey = `coach_r1_awareness`; break;
                    case `traffic`: cacDelta += 6; shareDelta += 0.3; coachKey = `coach_r1_traffic`; break;
                }

                switch (d.northstar) {
                    case `roi`: shareDelta += 0.8; coachKey = `coach_r1_roi`; break;
                    case `awareness`: shareDelta -= 0.4; coachKey = `coach_r1_nsbrand`; break;
                    case `spend`: shareDelta -= 0.6; cacDelta += 2; coachKey = `coach_r1_nsspend`; break;
                }

                // Ownership = Mazurek's marketing-led thesis (decision tree #4 / common error #5).
                // Ceding the pivot to IT or an agency must measurably cost the team: it is the
                // one move the board explicitly warned strips the CMO of strategic control.
                if (d.ownership >= 60) { shareDelta += 0.6; }
                else if (d.ownership <= 30) { shareDelta -= 2.5; cacDelta += 8; ds.cededControl = true; coachKey = `coach_r1_ceded`; }

                summaryKey = (d.split === `separate` && d.leak === `conversion` && d.northstar === `roi`) ? `sum_r1_good` : `sum_r1_weak`;
            } else if (round === 2) {
                // ---- Reallocate inside the frozen envelope (errors 1 & 5). ----
                const shift = d.brandShift / 100; // share of traditional/trade moved to digital

                // Digital share rises with redeployment, but with diminishing returns and
                // dependent on WHERE it goes.
                shareDelta += shift * 8;          // moving money to digital lifts share
                cacDelta += -shift * 10;          // more digital efficiency can lower CAC a little

                // Brand floor & over-cutting (decision tree #1: awareness is a CAC subsidy).
                // Traditional/trade is 62% of the budget; moving >55% of it = cutting brand to the bone.
                if (d.floor === `real`) {
                    brandDelta += 0;              // protected
                    if (shift > 0.55) { shift > 0.55 ? (ds.brandPenaltyPending += 2) : 0; } // floor caps the damage
                } else if (d.floor === `token`) {
                    if (shift > 0.45) { ds.brandPenaltyPending += 3; }
                } else { // nofloor
                    if (shift >= 0.30) { ds.brandPenaltyPending += 4; }
                }

                if (shift > 0.55) {
                    // Cutting brand media to the bone: immediate dip + queued delayed erosion.
                    // Eroding the demand the brand generates undercuts the very demand
                    // digital is trying to capture — so the headline share gain is hollow.
                    ds.cutBrandHard = true;
                    brandDelta -= 4;
                    ds.brandPenaltyPending += 4;
                    cacDelta += 14;               // buying customers you used to get for free
                    shareDelta -= shift * 5;      // less brand demand to capture -> share gain partly evaporates
                    coachKey = `coach_r2_cutbrand`;
                } else if (shift < 0.10) {
                    // Cutting too little starves digital growth.
                    coachKey = `coach_r2_timid`;
                }

                // Where the redeployed money goes (decision tree #5: CAC vs unit economics).
                switch (d.focus) {
                    case `balanced`: shareDelta += 2.2; convDelta += 0.05; cacDelta -= 6; coachKey = `coach_r2_balanced`; break;
                    case `cheapclicks`: shareDelta += 0.3; cacDelta -= 22; brandDelta -= 1; ds.cacChasing = true; coachKey = `coach_r2_cheapclicks`; break; // CAC looks great, unit economics rot
                    case `moretv`: brandDelta += 2; shareDelta -= 1.0; coachKey = `coach_r2_moretv`; break;
                }

                // Conversion target is aspirational here — spend alone barely moves it (needs R3 replatform).
                const ambition = d.convTarget - this.START_CONV; // 0..1.6
                convDelta += Math.min(0.06, ambition * 0.04);

                // Floor messaging if not already overridden by a sharper coach.
                if (d.floor === `real` && shift >= 0.20 && shift <= 0.45 && d.focus === `balanced`) {
                    coachKey = `coach_r2_good`;
                }

                summaryKey = (d.floor === `real` && d.focus === `balanced` && shift >= 0.20 && shift <= 0.45) ? `sum_r2_good` :
                             (ds.cutBrandHard ? `sum_r2_cutbrand` :
                             (d.focus === `cheapclicks` ? `sum_r2_cheap` : `sum_r2_weak`));
            } else if (round === 3) {
                // ---- Martech sequencing under a 12 mln zł cap (errors 2 & 3). ----
                // Greedy funding in the player's stated sequence priority, capped at the envelope.
                ds.martechSpent = 0;
                ds.replatform = false; ds.replatformPartial = false;
                ds.cdp = false; ds.attribution = false; ds.marketplace = false;

                const wishlist = [];
                if (d.replatform) wishlist.push(`replatform`);
                if (d.cdp) wishlist.push(`cdp`);
                if (d.attribution) wishlist.push(`attribution`);
                if (d.marketplace) wishlist.push(`marketplace`);

                // Order the wishlist by the stated sequencing discipline.
                const order = this._fundingOrder(d.sequence, wishlist);
                const cost = { replatform: this.COST_REPLATFORM, cdp: this.COST_CDP, attribution: this.COST_ATTRIBUTION, marketplace: this.COST_MARKETPLACE };
                let remaining = this.MARTECH;
                for (const item of order) {
                    const c = cost[item];
                    if (remaining >= c) {
                        remaining -= c; ds.martechSpent += c;
                        ds[item] = true;
                    } else if (item === `replatform` && remaining >= 5) {
                        // Partial replatform: funded but starved — stalls at ~1.6% conversion.
                        ds.replatformPartial = true; ds.martechSpent += remaining; remaining = 0;
                    }
                }
                ds.martechSpent = Math.round(ds.martechSpent * 10) / 10;

                const fundedCount = (ds.replatform ? 1 : 0) + (ds.cdp ? 1 : 0) + (ds.attribution ? 1 : 0) + (ds.marketplace ? 1 : 0);
                ds.spreadThin = (wishlist.length >= 3 && d.sequence === `spread`) || (d.replatform && !ds.replatform && ds.replatformPartial);

                // (a) Replatform — the conversion leverage play.
                if (ds.replatform) {
                    convDelta += 0.85; shareDelta += 3.5; coachKey = `coach_r3_replatform`;
                } else if (ds.replatformPartial) {
                    convDelta += 0.20; shareDelta += 0.8; coachKey = `coach_r3_partial`;
                }

                // (b) CDP + CRM — lowers CAC via retention.
                if (ds.cdp) { cacDelta -= 38; brandDelta += 1; shareDelta += 1.0; }

                // (c) Attribution — the ROI-defensibility capability.
                if (ds.attribution) { shareDelta += 0.8; cacDelta -= 6; }
                else { ds.skippedAttribution = true; }

                // (d) Allegro marketplace — fast demand capture, thinner margin.
                if (ds.marketplace) { shareDelta += 2.4; cacDelta -= 8; }

                // Sequencing discipline / mid-round Allegro temptation.
                if (d.sequence === `marketplace` && ds.marketplace && !ds.replatform) {
                    coachKey = `coach_r3_marketplacefirst`;
                } else if (d.sequence === `spread`) {
                    // Spreading thin starves the leverage play.
                    if (ds.replatformPartial || !ds.replatform) { shareDelta -= 1.5; convDelta -= 0.15; }
                    coachKey = `coach_r3_spread`;
                } else if (d.sequence === `foundation` && ds.replatform && ds.attribution) {
                    shareDelta += 0.8; coachKey = `coach_r3_foundation`;
                }

                if (ds.skippedAttribution && ds.replatform) {
                    coachKey = `coach_r3_noattrib`; // conversion up but cannot prove which channels drove it
                }

                summaryKey = (ds.replatform && ds.attribution) ? `sum_r3_good` :
                             (ds.spreadThin ? `sum_r3_spread` :
                             (ds.skippedAttribution ? `sum_r3_noattrib` : `sum_r3_weak`));
            } else if (round === 4) {
                // ---- Recover & defend before the board. ----
                // First, fire the delayed brand-erosion penalty queued in Round 2.
                if (ds.brandPenaltyPending > 0) {
                    brandDelta -= ds.brandPenaltyPending;
                    cacDelta += ds.brandPenaltyPending * 4; // eroded awareness raises blended CAC
                    ds.brandPenaltyPending = 0;
                }

                switch (d.narrative) {
                    case `causal`: shareDelta += 1.5; coachKey = `coach_r4_causal`; if (!ds.attribution) coachKey = `coach_r4_causalnoattrib`; break;
                    case `hitnumber`: shareDelta += 0.2; coachKey = `coach_r4_hitnumber`; break;
                    case `blame`: shareDelta -= 0.5; coachKey = `coach_r4_blame`; break;
                }

                switch (d.metric) {
                    case `unitecon`: cacDelta -= 6; shareDelta += 0.8; break;
                    case `caconly`: if (ds.cacChasing) { coachKey = `coach_r4_caconly`; } break;
                    case `share`: coachKey = `coach_r4_shareonly`; break;
                }

                switch (d.team) {
                    case `align`: shareDelta += 1.2; brandDelta += 1; coachKey = `coach_r4_align`; break;
                    case `winargument`: brandDelta -= 2; coachKey = `coach_r4_winargument`; break;
                    case `ignore`: brandDelta -= 1; coachKey = `coach_r4_ignoreteam`; break;
                }

                if (d.conviction >= 60 && d.narrative === `causal`) { shareDelta += 0.4; }
                else if (d.conviction <= 25) { shareDelta -= 0.3; }

                summaryKey = (d.narrative === `causal` && d.metric === `unitecon` && d.team === `align`) ? `sum_r4_good` : `sum_r4_weak`;
            }

            // ---- Apply deltas (clamped to plausible ranges). ----
            ds.share = Math.max(0, Math.min(60, Math.round((ds.share + shareDelta) * 10) / 10));
            ds.cac = Math.max(80, Math.min(500, Math.round(ds.cac + cacDelta)));
            ds.conversion = Math.max(0.5, Math.min(4.0, Math.round((ds.conversion + convDelta) * 100) / 100));
            ds.brand = Math.max(40, Math.min(90, Math.round((ds.brand + brandDelta) * 10) / 10));

            // ---- Eroded awareness raises the floor on CAC: a low brand is a permanent CAC tax. ----
            if (ds.brand < 60) { ds.cac = Math.min(500, ds.cac + Math.round((60 - ds.brand) * 1.5)); }

            // ---- Half-year checkpoint after Round 2 (≥16% by 30 Sep). ----
            if (round === 2 && ds.share < this.CHECKPOINT) {
                ds.checkpointMiss = true;
            } else if (round === 2 && ds.share >= this.CHECKPOINT) {
                ds.checkpointMiss = false;
            }

            // ---- Transformation ROI: incremental online margin vs. the spend it consumed. ----
            // Computed from Round 3 (once the martech capital is deployed) and refined in Round 4.
            if (round >= 3) {
                ds.roi = this._computeRoi(ds);
                ds.roiSet = true;
            }

            ds.shareHistory.push(ds.share);
            ds.convHistory.push(ds.conversion);
            ds.brandHistory.push(ds.brand);
            ds.cacHistory.push(ds.cac);

            const coachMsg = window.mySimulation.t(coachKey);
            ds.lastCoach = coachMsg;
            const coachEl = document.getElementById(`coachText`);
            if (coachEl) coachEl.innerHTML = coachMsg;

            const self = this;
            setTimeout(function() {
                self._updateBriefing({ currentPeriod: state.currentPeriod + 1 });
            }, 500);

            // v1.1.0 - persist the composite where the gradebook reads it (was never written).
            const _score = this._composite(ds);
            if (!ds.performance || typeof ds.performance !== `object`) ds.performance = {};
            ds.performance.overallScore = _score;
            ds.score = _score;

            return {
                period: state.currentPeriod,
                score: _score,
                overallScore: _score,
                share: ds.share,
                shareDelta: Math.round(shareDelta * 10) / 10,
                cac: ds.cac,
                conversion: ds.conversion,
                brand: ds.brand,
                roi: ds.roi,
                roiSet: ds.roiSet,
                checkpointMiss: ds.checkpointMiss,
                summary: window.mySimulation.t(summaryKey),
                coach: coachMsg
            };
        }

        _fundingOrder(sequence, wishlist) {
            // Returns the wishlist re-ordered by the player's stated sequencing discipline.
            const has = (x) => wishlist.includes(x);
            if (sequence === `foundation`) {
                const pref = [`replatform`, `attribution`, `cdp`, `marketplace`];
                return pref.filter(has);
            }
            if (sequence === `marketplace`) {
                const pref = [`marketplace`, `cdp`, `attribution`, `replatform`];
                return pref.filter(has);
            }
            // spread: try to fund the cheap ones first so breadth wins and leverage starves
            const pref = [`attribution`, `marketplace`, `cdp`, `replatform`];
            return pref.filter(has);
        }

        _computeRoi(ds) {
            // Stylised transformation-ROI model (%): incremental online margin generated
            // versus the martech capital + the efficiency of the redeployed spend.
            // Online revenue scales with conversion (vs the 1.4% baseline) and digital share.
            const convGain = (ds.conversion - this.START_CONV) / this.START_CONV;     // proportional conversion lift
            const shareGain = (ds.share - this.START_SHARE) / this.START_SHARE;        // proportional share lift
            const cacPenalty = (ds.cac - this.START_CAC) / this.START_CAC;             // +ve if CAC rose (bad)
            const brandPenalty = (this.START_BRAND - ds.brand) / this.START_BRAND;     // +ve if awareness fell (bad)

            // Incremental margin proxy (indexed). Attribution makes the ROI provable AND
            // unlocks reallocation efficiency; without it the board discounts the claim.
            let margin = (convGain * 55) + (shareGain * 35) - (cacPenalty * 40) - (brandPenalty * 50);
            if (ds.attribution) margin += 8; else margin -= 10;
            if (ds.cacChasing) margin -= 12;  // discount-seeker AOV drags realised margin
            if (ds.cededControl) margin -= 18; // pivot run by IT/agency: marketing cannot claim the return as its own

            // Spend intensity: the martech capital consumed (of 12) is the denominator weight.
            const spendDrag = (ds.martechSpent / this.MARTECH) * 14;
            const roi = Math.round(margin - spendDrag);
            return Math.max(-60, Math.min(120, roi));
        }

        setupUI(uiManager) {
            uiManager.bind(`currentDay`, `currentPeriod`);
            uiManager.bind(`maxPeriods`, `maxPeriods`);

            const self = this;

            uiManager.bind(`shareDisplay`, `domainState.share`, (v) => {
                const n = Number(v);
                const card = document.querySelector(`.digitalpivot-card-share`);
                if (card) {
                    card.classList.toggle(`digitalpivot-good`, n >= self.TARGET_SHARE);
                    card.classList.toggle(`digitalpivot-warn`, n >= self.CHECKPOINT && n < self.TARGET_SHARE);
                    card.classList.toggle(`digitalpivot-loss`, n < self.CHECKPOINT);
                }
                return `${self._fmt1(n)}%`;
            });

            uiManager.bind(`cacDisplay`, `domainState.cac`, (v) => {
                const n = Math.round(Number(v));
                const card = document.querySelector(`.digitalpivot-card-cac`);
                if (card) {
                    card.classList.toggle(`digitalpivot-good`, n <= 200);
                    card.classList.toggle(`digitalpivot-loss`, n >= 280);
                }
                return `${n} zł`;
            });

            uiManager.bind(`convDisplay`, `domainState.conversion`, (v) => `${self._fmt2(Number(v))}%`);

            uiManager.bind(`brandDisplay`, `domainState.brand`, (v) => {
                const n = Number(v);
                const card = document.querySelector(`.digitalpivot-card-brand`);
                if (card) {
                    card.classList.toggle(`digitalpivot-loss`, n < 64);
                }
                return `${Math.round(n)}%`;
            });

            uiManager.bind(`roiDisplay`, `domainState.roi`, (v) => {
                const ds = window.mySimulation.state.domainState;
                const bar = document.querySelector(`.digitalpivot-roi-bar`);
                if (!ds || !ds.roiSet) {
                    if (bar) bar.classList.remove(`digitalpivot-roi-good`, `digitalpivot-roi-warn`, `digitalpivot-roi-loss`);
                    return `—`;
                }
                const n = Math.round(Number(v));
                if (bar) {
                    bar.classList.toggle(`digitalpivot-roi-good`, n >= 30);
                    bar.classList.toggle(`digitalpivot-roi-warn`, n >= 0 && n < 30);
                    bar.classList.toggle(`digitalpivot-roi-loss`, n < 0);
                }
                return `${n > 0 ? `+` : ``}${n}%`;
            });

            // Ownership slider readout.
            this._wireSlider(`ownershipInput`, `ownershipReadout`);
            // Brand-shift slider readout.
            this._wireSlider(`brandShiftInput`, `brandShiftReadout`);

            // Martech budget live readout (Round 3).
            const ids = [`replatformInput`, `cdpInput`, `attributionInput`, `marketplaceInput`];
            const recompute = function() {
                const cost = { replatformInput: self.COST_REPLATFORM, cdpInput: self.COST_CDP, attributionInput: self.COST_ATTRIBUTION, marketplaceInput: self.COST_MARKETPLACE };
                let total = 0;
                ids.forEach((id) => { const el = document.getElementById(id); if (el && el.checked) total += cost[id]; });
                const out = document.getElementById(`martechCommitted`);
                if (out) out.textContent = self._fmt1(total);
                const box = document.querySelector(`.digitalpivot-budget-readout`);
                if (box) box.classList.toggle(`digitalpivot-over`, total > self.MARTECH);
            };
            ids.forEach((id) => { const el = document.getElementById(id); if (el) el.addEventListener(`change`, recompute); });
            recompute();
        }

        _wireSlider(inputId, readoutId) {
            const inp = document.getElementById(inputId);
            const out = document.getElementById(readoutId);
            if (inp && out) {
                out.textContent = inp.value;
                inp.addEventListener(`input`, function() { out.textContent = inp.value; });
            }
        }

        _fmt1(v) {
            const lang = (window.mySimulation && window.mySimulation.language) ? window.mySimulation.language : `en`;
            const s = (Math.round(v * 10) / 10).toFixed(1);
            return lang === `es` ? s.replace(`.`, `,`) : s;
        }

        _fmt2(v) {
            const lang = (window.mySimulation && window.mySimulation.language) ? window.mySimulation.language : `en`;
            const s = (Math.round(v * 100) / 100).toFixed(2);
            return lang === `es` ? s.replace(`.`, `,`) : s;
        }

        getChartConfig() {
            return {
                pivotChart: {
                    type: `line`,
                    data: {
                        labels: [],
                        datasets: [
                            {
                                label: `Digital revenue share (%)`,
                                data: [],
                                borderColor: `#4b3a86`,
                                backgroundColor: `rgba(75,58,134,0.12)`,
