        getChartData(state) {
            const ds = state.domainState;
            const labels = ds.shareHistory.map((_, i) => (i === 0 ? window.mySimulation.t(`chart_start`) : `Q` + i));
            // Conversion is ~1.4–2.6 — scale ×10 to read against the share axis.
            const convScaled = ds.convHistory.map((v) => Math.round(v * 100) / 10);
            return {
                pivotChart: {
                    labels: labels,
                    datasets: [
                        { data: ds.shareHistory.map((v) => Math.round(v * 10) / 10) },
                        { data: convScaled },
                        { data: ds.brandHistory.map((v) => Math.round(v)) }
                    ]
                }
            };
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            const ds = window.mySimulation.state.domainState;
            const share = Math.round(ds.share * 10) / 10;
            const cac = Math.round(ds.cac);
            const conversion = Math.round(ds.conversion * 100) / 100;
            const brand = Math.round(ds.brand);
            const roi = Math.round(ds.roi);

            const hitTarget = share >= this.TARGET_SHARE;
            const passedCheckpoint = !ds.checkpointMiss;
            const cacDown = cac <= this.START_CAC;
            const convUp = conversion >= 2.2;
            const brandHeld = brand >= 66;
            const provable = ds.attribution;

            // Composite: share, conversion, CAC (inverted), brand, ROI — balanced.
            const shareScore = Math.min(100, (share / this.TARGET_SHARE) * 100);
            const convScore = Math.min(100, ((conversion - this.START_CONV) / (this.BENCH_CONV - this.START_CONV)) * 100);
            const cacScore = Math.max(0, Math.min(100, (this.START_CAC / cac) * 100));
            const brandScore = Math.min(100, (brand / this.START_BRAND) * 100);
            const roiScore = Math.max(0, Math.min(100, 50 + roi * 0.6));
            // v1.1.0 - reuse the shared helper so completion composite == final period's persisted score.
            const composite = this._composite(ds);

            let pattern = `mixed`;
            if (ds.cutBrandHard && brand < 66) pattern = `brandcut`;
            else if (ds.spreadThin) pattern = `spreadthin`;
            else if (ds.skippedAttribution) pattern = `noattribution`;
            else if (ds.cacChasing) pattern = `cacchasing`;
            else if (ds.cededControl) pattern = `ceded`;
            else if (hitTarget && convUp && brandHeld && provable) pattern = `transformation`;

            // v1.1.0 - tier labels moved to i18n keys (were hardcoded English).
            // Ceding the pivot to IT/agency forfeits the marketing-led verdicts even if the numbers land.
            let tierKey = `grade_missed`;
            if (!ds.cededControl && hitTarget && convUp && brandHeld && provable && roi >= 30 && composite >= 75) tierKey = `grade_transformation`;
            else if (!ds.cededControl && hitTarget && brandHeld && provable) tierKey = `grade_provable`;
            else if (hitTarget && !brandHeld) tierKey = `grade_brandlost`;
            else if (!passedCheckpoint) tierKey = `grade_checkpoint`;
            else if (composite >= 55) tierKey = `grade_partial`;
            const performance = window.mySimulation.t(tierKey);

            const insights = [];
            if (pattern === `transformation`) insights.push(window.mySimulation.t(`insight_transformation`));
            else if (pattern === `brandcut`) insights.push(window.mySimulation.t(`insight_brandcut`));
            else if (pattern === `spreadthin`) insights.push(window.mySimulation.t(`insight_spreadthin`));
            else if (pattern === `noattribution`) insights.push(window.mySimulation.t(`insight_noattribution`));
            else if (pattern === `cacchasing`) insights.push(window.mySimulation.t(`insight_cacchasing`));
            else if (pattern === `ceded`) insights.push(window.mySimulation.t(`insight_ceded`));
            else insights.push(window.mySimulation.t(`insight_mixed`));

            if (!passedCheckpoint) insights.push(window.mySimulation.t(`insight_checkpoint`));
            if (!provable) insights.push(window.mySimulation.t(`insight_noattribution`));
            if (!brandHeld) insights.push(window.mySimulation.t(`insight_brandlow`));
            if (!hitTarget) insights.push(window.mySimulation.t(`insight_targetmiss`));
            if (hitTarget && brandHeld && conversion < 2.0) insights.push(window.mySimulation.t(`insight_convlow`));

            return {
                share: share,
                cac: cac,
                conversion: conversion,
                brand: brand,
                roi: roi,
                hitTarget: hitTarget,
                passedCheckpoint: passedCheckpoint,
                cacDown: cacDown,
                convUp: convUp,
                brandHeld: brandHeld,
                provable: provable,
                pattern: pattern,
                composite: composite,
                performance: performance,
                tierKey: tierKey,
                insights: insights
            };
        }

        formatCompletionMessage(summary) {
            const t = (k) => window.mySimulation.t(k);
            if (!summary || summary.composite == null) {
                return `<div class="dpv-cm"><p class="dpv-cm-incomplete">` + t(`cm_incomplete`) + `</p></div>`;
            }
            const s = summary;
            const chip = (ok, label) => `<span class="dpv-cm-chip ` + (ok ? `dpv-cm-ok` : `dpv-cm-no`) + `">` +
                `<span class="dpv-cm-ico">` + (ok ? `✓` : `✗`) + `</span>` + label + ` · ` +
                (ok ? t(`cm_met`) : t(`cm_missed`)) + `</span>`;
            const kpi = (label, val, sub) => `<div class="dpv-cm-kpi"><div class="dpv-cm-kpi-val">` + val +
                `</div><div class="dpv-cm-kpi-lbl">` + label + `</div>` +
                (sub ? `<div class="dpv-cm-kpi-sub">` + sub + `</div>` : ``) + `</div>`;
            const insights = (s.insights || []).map((x) => `<li>` + x + `</li>`).join(``);
            return `` +
`<div class="dpv-cm">` +
  `<div class="dpv-cm-head">` +
    `<div class="dpv-cm-score"><div class="dpv-cm-score-num">` + Math.round(s.composite) +
       `<span class="dpv-cm-score-den">/100</span></div>` +
       `<div class="dpv-cm-score-lbl">` + t(`cm_score`) + `</div></div>` +
    `<div class="dpv-cm-verdict"><div class="dpv-cm-verdict-lbl">` + t(`cm_verdict`) + `</div>` +
       `<div class="dpv-cm-verdict-tier">` + s.performance + `</div></div>` +
  `</div>` +
  `<div class="dpv-cm-section"><div class="dpv-cm-section-h">` + t(`cm_targets`) + `</div>` +
    `<div class="dpv-cm-chips">` + chip(!!s.hitTarget, t(`cm_t_target`)) + chip(!!s.convUp, t(`cm_t_conv`)) +
      chip(!!s.brandHeld, t(`cm_t_brand`)) + chip(!!s.provable, t(`cm_t_provable`)) + `</div></div>` +
  `<div class="dpv-cm-section"><div class="dpv-cm-section-h">` + t(`cm_kpis`) + `</div>` +
    `<div class="dpv-cm-kpis">` +
      kpi(t(`cm_lbl_share`), Number(s.share).toFixed(1) + `%`, t(`cm_sub_share`)) +
      kpi(t(`cm_lbl_conv`), Number(s.conversion).toFixed(2) + `%`, t(`cm_sub_conv`)) +
      kpi(t(`cm_lbl_brand`), Math.round(s.brand), t(`cm_sub_brand`)) +
      kpi(t(`cm_lbl_roi`), Math.round(s.roi) + `%`, t(`cm_sub_roi`)) +
    `</div></div>` +
  (insights ? `<div class="dpv-cm-section"><div class="dpv-cm-section-h">` + t(`cm_insights`) +
      `</div><ul class="dpv-cm-insights">` + insights + `</ul></div>` : ``) +
`</div>`;
        }

        getHint(state, results) {
            if (!results) return null;
            const ds = state.domainState;
            const round = state.currentPeriod;
            if (ds.checkpointMiss && round >= 2) return window.mySimulation.t(`hint_checkpoint`);
            if (ds.brand < 64) return window.mySimulation.t(`hint_brand`);
            if (ds.cutBrandHard && round <= 3) return window.mySimulation.t(`hint_brandpending`);
            if (ds.skippedAttribution && round >= 3) return window.mySimulation.t(`hint_attribution`);
            if (ds.cacChasing) return window.mySimulation.t(`hint_cacchasing`);
            if (ds.spreadThin) return window.mySimulation.t(`hint_spreadthin`);
            if (ds.share >= this.TARGET_SHARE && ds.brand >= 66 && ds.attribution) return window.mySimulation.t(`hint_strong`);
            return null;
        }

