                { key: `results.share`, label: `Share`, i18nKey: `col_share`, formatter: (v) => `${self._fmt1(Number(v))}%` },
                { key: `results.cac`, label: `CAC`, i18nKey: `col_cac`, formatter: (v) => `${Math.round(v)} zł` },
                { key: `results.conversion`, label: `Conv`, i18nKey: `col_conv`, formatter: (v) => `${self._fmt2(Number(v))}%` },
                { key: `results.brand`, label: `Brand`, i18nKey: `col_brand`, formatter: (v) => `${Math.round(v)}%` }
            ];
        }

